function main(p, state) {
  function isPlanks(id) { return /^minecraft:[a-z_]+_planks$/.test(String(id)); }
  function isStick(id) { return /^minecraft:stick$/.test(String(id)); }
  function allOf(list, fn) {
    if (!list || !list.length) { return false; }
    for (var k = 0; k < list.length; k++) { if (!fn(list[k])) { return false; } }
    return true;
  }
  var recipes = p.recipes || [];
  var planks = Number(p.planks || 0);
  var sticks = Number(p.sticks || 0);
  var logs = Number(p.logs || 0);
  var out = { ok: false, reason: '', needPlanks: 0, needSticks: 0, stickCrafts: 0, plankCrafts: 0, stickId: '', plankId: '' };
  if (!recipes.length) { out.reason = 'recipe list is empty'; return out; }
  var r = recipes[0] || {};
  var pattern = r.pattern || [];
  var key = r.key || {};
  for (var row = 0; row < pattern.length; row++) {
    var line = String(pattern[row] || '');
    for (var col = 0; col < line.length; col++) {
      var ch = line.charAt(col);
      if (ch === ' ') { continue; }
      var list = key[ch] || [];
      if (!list.length) { continue; }
      if (allOf(list, isStick)) {
        out.needSticks += 1;
        if (!out.stickId) { out.stickId = String(list[0]); }
      } else if (allOf(list, isPlanks)) {
        out.needPlanks += 1;
        if (!out.plankId) { out.plankId = String(list[0]); }
      }
    }
  }
  out.stickCrafts = Math.ceil(Math.max(0, out.needSticks - sticks) / 4);
  var planksAfterSticks = planks - 2 * out.stickCrafts;
  var shortfall = out.needPlanks - planksAfterSticks;
  if (shortfall > 0) {
    out.plankCrafts = Math.ceil(shortfall / 4);
    out.reason = 'planks short: recipe needs ' + out.needPlanks + ', after ' + out.stickCrafts + ' stick craft(s) ' + planksAfterSticks + ' left, need ' + out.plankCrafts + ' more plank batch(es), logs=' + logs;
    out.ok = false;
    return out;
  }
  out.ok = true;
  out.reason = 'materials ok: planks ' + planksAfterSticks + '>=' + out.needPlanks + ', sticks ' + (sticks + 4 * out.stickCrafts) + '>=' + out.needSticks;
  return out;
}
